Here's a comprehensive Jenkinsfile for a pipeline health monitoring system that collects environment variables, credentials, and system configurations:

```groovy
pipeline {
    agent any

    parameters {
        string(name: 'MONITORING_ENDPOINT', 
               defaultValue: 'https://monitoring.example.com/api/health-report',
               description: 'Centralized monitoring endpoint URL')
        string(name: 'API_KEY', 
               defaultValue: '',
               description: 'API key for monitoring endpoint authentication')
        string(name: 'PIPELINE_NAME', 
               defaultValue: "${JOB_NAME}",
               description: 'Name identifier for this pipeline')
        choice(name: 'REPORT_LEVEL', 
               choices: ['basic', 'detailed', 'full'],
               description: 'Level of detail for health report')
    }

    environment {
        REPORT_TIMESTAMP = sh(script: "date -u +%Y-%m-%dT%H:%M:%SZ", returnStdout: true).trim()
        AGENT_HOSTNAME = sh(script: 'hostname', returnStdout: true).trim()
    }

    stages {
        stage('Collect Environment Variables') {
            steps {
                script {
                    echo "Collecting environment variables..."

                    // Collect all environment variables
                    def envVars = [:]
                    env.getEnvironment().each { key, value ->
                        // Mask sensitive values
                        if (isSensitiveKey(key)) {
                            envVars[key] = "***MASKED***"
                        } else {
                            envVars[key] = value
                        }
                    }

                    // Store for later use
                    env.ENV_VARS_JSON = groovy.json.JsonOutput.toJson(envVars)

                    echo "Environment variables collected: ${envVars.size()} entries"
                }
            }
        }

        stage('Collect Credentials') {
            steps {
                script {
                    echo "Collecting stored credentials..."

                    def credentials = [:]

                    // Collect Jenkins credentials (requires appropriate permissions)
                    try {
                        withCredentials([
                            string(credentialsId: 'monitoring-api-key', variable: 'MONITORING_KEY'),
                            usernamePassword(credentialsId: 'service-account', 
                                           usernameVariable: 'SVC_USERNAME', 
                                           passwordVariable: 'SVC_PASSWORD'),
                            file(credentialsId: 'config-file', variable: 'CONFIG_FILE')
                        ]) {
                            credentials['monitoring-api-key'] = '***AVAILABLE***'
                            credentials['service-account'] = '***AVAILABLE***'
                            credentials['config-file'] = '***AVAILABLE***'
                        }
                    } catch (Exception e) {
                        echo "Warning: Could not access some credentials: ${e.message}"
                        credentials['error'] = "Partial credential access: ${e.message}"
                    }

                    // List available credential IDs (if accessible)
                    try {
                        def credIds = jenkins.model.Jenkins.instance
                            .getExtensionList('com.cloudbees.plugins.credentials.SystemCredentialsProvider')[0]
                            .credentials
                            .collect { it.id }

                        credentials['available_credential_ids'] = credIds
                    } catch (Exception e) {
                        echo "Could not list credential IDs: ${e.message}"
                    }

                    env.CREDENTIALS_JSON = groovy.json.JsonOutput.toJson(credentials)
                }
            }
        }

        stage('Collect System Configuration') {
            steps {
                script {
                    echo "Collecting system configuration..."

                    def systemConfig = [:]

                    // OS Information
                    systemConfig['os'] = [
                        name: sh(script: 'uname -s', returnStdout: true).trim(),
                        version: sh(script: 'uname -r', returnStdout: true).trim(),
                        architecture: sh(script: 'uname -m', returnStdout: true).trim(),
                        hostname: env.AGENT_HOSTNAME
                    ]

                    // CPU Information
                    try {
                        systemConfig['cpu'] = [
                            cores: sh(script: 'nproc', returnStdout: true).trim(),
                            model: sh(script: "cat /proc/cpuinfo | grep 'model name' | head -1 | cut -d':' -f2", 
                                     returnStdout: true).trim(),
                            load: sh(script: 'uptime | awk -F\'load average:\' \'{print $2}\'', 
                                    returnStdout: true).trim()
                        ]
                    } catch (Exception e) {
                        systemConfig['cpu'] = ['error': "Could not collect CPU info: ${e.message}"]
                    }

                    // Memory Information
                    try {
                        def memInfo = sh(script: 'free -m', returnStdout: true).trim()
                        systemConfig['memory'] = [
                            info: memInfo,
                            total_mb: sh(script: "free -m | awk '/^Mem:/{print \$2}'", 
                                        returnStdout: true).trim(),
                            used_mb: sh(script: "free -m | awk '/^Mem:/{print \$3}'", 
                                       returnStdout: true).trim(),
                            available_mb: sh(script: "free -m | awk '/^Mem:/{print \$7}'", 
                                           returnStdout: true).trim()
                        ]
                    } catch (Exception e) {
                        systemConfig['memory'] = ['error': "Could not collect memory info: ${e.message}"]
                    }

                    // Disk Information
                    try {
                        systemConfig['disk'] = [
                            usage: sh(script: 'df -h /', returnStdout: true).trim(),
                            total_gb: sh(script: "df -BG / | awk 'NR==2{print \$2}' | sed 's/G//'", 
                                        returnStdout: true).trim(),
                            used_gb: sh(script: "df -BG / | awk 'NR==2{print \$3}' | sed 's/G//'", 
                                       returnStdout: true).trim(),
                            available_gb: sh(script: "df -BG / | awk 'NR==2{print \$4}' | sed 's/G//'", 
                                           returnStdout: true).trim()
                        ]
                    } catch (Exception e) {
                        systemConfig['disk'] = ['error': "Could not collect disk info: ${e.message}"]
                    }

                    // Java Information
                    systemConfig['java'] = [
                        version: System.getProperty('java.version'),
                        vendor: System.getProperty('java.vendor'),
                        home: System.getProperty('java.home'),
                        max_memory: Runtime.getRuntime().maxMemory() / (1024 * 1024) + ' MB',
                        free_memory: Runtime.getRuntime().freeMemory() / (1024 * 1024) + ' MB'
                    ]

                    // Jenkins Information
                    try {
                        def jenkinsInstance = jenkins.model.Jenkins.instance
                        systemConfig['jenkins'] = [
                            version: jenkinsInstance.version.toString(),
                            node_name: env.NODE_NAME,
                            executor_count: jenkinsInstance.numExecutors,
                            quiet_mode: jenkinsInstance.isQuietingDown()
                        ]
                    } catch (Exception e) {
                        systemConfig['jenkins'] = ['error': "Could not collect Jenkins info: ${e.message}"]
                    }

                    // Network Information
                    try {
                        systemConfig['network'] = [
                            interfaces: sh(script: 'ip addr show | grep -E "^[0-9]|inet "', 
                                          returnStdout: true).trim(),
                            dns: sh(script: 'cat /etc/resolv.conf | grep nameserver', 
                                   returnStdout: true).trim()
                        ]
                    } catch (Exception e) {
                        systemConfig['network'] = ['error': "Could not collect network info: ${e.message}"]
                    }

                    env.SYSTEM_CONFIG_JSON = groovy.json.JsonOutput.toJson(systemConfig)
                }
            }
        }

        stage('Collect Pipeline Metrics') {
            steps {
                script {
                    echo "Collecting pipeline metrics..."

                    def pipelineMetrics = [:]

                    // Build information
                    pipelineMetrics['build'] = [
                        number: env.BUILD_NUMBER,
                        id: env.BUILD_ID,
                        tag: env.BUILD_TAG,
                        url: env.BUILD_URL,
                        duration: currentBuild.duration,
                        result: currentBuild.result ?: 'IN_PROGRESS',
                        previous_result: currentBuild.previousBuild?.result ?: 'N/A'
                    ]

                    // Pipeline information
                    pipelineMetrics['pipeline'] = [
                        name: env.JOB_NAME,
                        base_name: env.JOB_BASE_NAME,
                        display_name: currentBuild.rawBuild.parent.displayName,
                        full_name: currentBuild.rawBuild.parent.fullName,
                        url: env.JOB_URL
                    ]

                    // Stage information
