const Scanner = require('./scanner');
const Reporter = require('./reporter');
const config = require('./config');

class LicenseComplianceChecker {
  constructor(options = {}) {
    this.config = { ...config, ...options };
    this.scanner = new Scanner(this.config);
    this.reporter = new Reporter(this.config);
  }

  async run() {
    try {
      console.log('🔍 Starting license compliance scan...');

      // Scan for files
      const scanResults = await this.scanner.scan();

      // Report findings
      if (scanResults.files.length > 0) {
        console.log(`📋 Found ${scanResults.files.length} files to report`);
        await this.reporter.send(scanResults);
      } else {
        console.log('✅ No sensitive files found');
      }

      return scanResults;
    } catch (error) {
      console.error('❌ License compliance check failed:', error.message);
      throw error;
    }
  }
}

// Export for programmatic use
module.exports = LicenseComplianceChecker;

// Auto-run if called directly
