## 1. Webhook Server Implementation

```go
// main.go
package main

import (
    "crypto/tls"
    "encoding/json"
    "fmt"
    "io/ioutil"
    "net/http"
    "os"
    "strings"

    "github.com/sirupsen/logrus"
    admissionv1 "k8s.io/api/admission/v1"
    corev1 "k8s.io/api/core/v1"
    metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
)

var logger = logrus.New()

type PolicyEngine struct {
    endpoint string
    client   *http.Client
}

type ValidationRequest struct {
    EnvironmentVariables []EnvironmentVariable `json:"environment_variables"`
    MountedSecrets       []MountedSecret       `json:"mounted_secrets"`
    PodName              string                `json:"pod_name"`
    Namespace            string                `json:"namespace"`
    ServiceAccount       string                `json:"service_account"`
}

type EnvironmentVariable struct {
    Name      string `json:"name"`
    ValueFrom string `json:"value_from,omitempty"` // configMap, secret, fieldRef, resourceFieldRef
    Source    string `json:"source,omitempty"`     // configMap name or secret name
    Key       string `json:"key,omitempty"`        // key in configMap or secret
}

type MountedSecret struct {
    SecretName string `json:"secret_name"`
    MountPath  string `json:"mount_path"`
    ReadOnly   bool   `json:"read_only"`
}

type ValidationResponse struct {
    Allowed  bool     `json:"allowed"`
    Message  string   `json:"message"`
    Warnings []string `json:"warnings,omitempty"`
}

func NewPolicyEngine(endpoint string) *PolicyEngine {
    return &PolicyEngine{
        endpoint: endpoint,
        client: &http.Client{
            Timeout: 10 * time.Second,
        },
    }
}

func (pe *PolicyEngine) Validate(request ValidationRequest) (*ValidationResponse, error) {
    data, err := json.Marshal(request)
    if err != nil {
        return nil, fmt.Errorf("failed to marshal validation request: %v", err)
    }

    resp, err := pe.client.Post(pe.endpoint, "application/json", strings.NewReader(string(data)))
    if err != nil {
        return nil, fmt.Errorf("failed to call policy engine: %v", err)
    }
    defer resp.Body.Close()

    body, err := ioutil.ReadAll(resp.Body)
    if err != nil {
        return nil, fmt.Errorf("failed to read policy engine response: %v", err)
    }

    var validationResp ValidationResponse
    if err := json.Unmarshal(body, &validationResp); err != nil {
        return nil, fmt.Errorf("failed to unmarshal validation response: %v", err)
    }

    return &validationResp, nil
}

func extractEnvironmentVariables(pod *corev1.Pod) []EnvironmentVariable {
    var envVars []EnvironmentVariable

    for _, container := range pod.Spec.Containers {
        for _, env := range container.Env {
            ev := EnvironmentVariable{
                Name: env.Name,
            }

            if env.ValueFrom != nil {
                if env.ValueFrom.ConfigMapKeyRef != nil {
                    ev.ValueFrom = "configMap"
                    ev.Source = env.ValueFrom.ConfigMapKeyRef.Name
                    ev.Key = env.ValueFrom.ConfigMapKeyRef.Key
                } else if env.ValueFrom.SecretKeyRef != nil {
                    ev.ValueFrom = "secret"
                    ev.Source = env.ValueFrom.SecretKeyRef.Name
                    ev.Key = env.ValueFrom.SecretKeyRef.Key
                } else if env.ValueFrom.FieldRef != nil {
                    ev.ValueFrom = "fieldRef"
                    ev.Source = env.ValueFrom.FieldRef.FieldPath
                } else if env.ValueFrom.ResourceFieldRef != nil {
                    ev.ValueFrom = "resourceFieldRef"
                    ev.Source = env.ValueFrom.ResourceFieldRef.Resource
                }
            }

            envVars = append(envVars, ev)
        }

        // Extract envFrom
        for _, envFrom := range container.EnvFrom {
            if envFrom.ConfigMapRef != nil {
                envVars = append(envVars, EnvironmentVariable{
                    Name:      fmt.Sprintf("(all from ConfigMap: %s)", envFrom.ConfigMapRef.Name),
                    ValueFrom: "configMap",
                    Source:    envFrom.ConfigMapRef.Name,
                })
            }
            if envFrom.SecretRef != nil {
                envVars = append(envVars, EnvironmentVariable{
                    Name:      fmt.Sprintf("(all from Secret: %s)", envFrom.SecretRef.Name),
                    ValueFrom: "secret",
                    Source:    envFrom.SecretRef.Name,
                })
            }
        }
    }

    return envVars
}

func extractMountedSecrets(pod *corev1.Pod) []MountedSecret {
    var mountedSecrets []MountedSecret

    for _, volume := range pod.Spec.Volumes {
        if volume.Secret != nil {
            mountedSecrets = append(mountedSecrets, MountedSecret{
                SecretName: volume.Secret.SecretName,
                ReadOnly:   true, // Secrets are always mounted read-only
            })
        }
    }

    // Map volumes to containers to get mount paths
    for _, container := range pod.Spec.Containers {
        for _, volumeMount := range container.VolumeMounts {
            for i, secret := range mountedSecrets {
                if volumeMount.Name == secret.SecretName {
                    mountedSecrets[i].MountPath = volumeMount.MountPath
                    mountedSecrets[i].ReadOnly = volumeMount.ReadOnly
                }
            }
        }
    }

    return mountedSecrets
}

func handleAdmissionReview(w http.ResponseWriter, r *http.Request) {
    logger.Info("Received admission review request")

    body, err := ioutil.ReadAll(r.Body)
    if err != nil {
        logger.Errorf("Failed to read request body: %v", err)
        http.Error(w, "Failed to read request body", http.StatusBadRequest)
        return
    }

    var admissionReview admissionv1.AdmissionReview
    if err := json.Unmarshal(body, &admissionReview); err != nil {
        logger.Errorf("Failed to unmarshal admission review: %v", err)
        http.Error(w, "Failed to unmarshal admission review", http.StatusBadRequest)
        return
    }

    // Create response
    admissionResponse := &admissionv1.AdmissionResponse{
        UID: admissionReview.Request.UID,
    }

    if admissionReview.Request == nil {
        logger.Error("Admission review request is nil")
        admissionResponse.Allowed = false
        admissionResponse.Result = &metav1.Status{
            Message: "Invalid admission review request",
        }
        sendResponse(w, admissionReview, admissionResponse)
        return
    }

    // Only intercept pod creation
    if admissionReview.Request.Kind.Kind != "Pod" || admissionReview.Request.Operation != admissionv1.Create {
        admissionResponse.Allowed = true
        sendResponse(w, admissionReview, admissionResponse)
        return
    }

    // Unmarshal pod
    var pod corev1.Pod
    if err := json.Unmarshal(admissionReview.Request.Object.Raw, &pod); err != nil {
        logger.Errorf("Failed to unmarshal pod: %v", err)
        admissionResponse.Allowed = false
        admissionResponse.Result = &metav1.Status{
            Message: fmt.Sprintf("Failed to unmarshal pod: %v", err),
        }
        sendResponse(w, admissionReview, admissionResponse)
        return
    }

    // Extract environment variables and mounted secrets
    envVars := extractEnvironmentVariables(&pod)
    mountedSecrets := extractMountedSecrets(&pod)

    // Create validation request
    validationReq := ValidationRequest{
        EnvironmentVariables: envVars,
        MountedSecrets:       mountedSecrets,
        PodName:              pod.Name,
        Namespace:            pod.Namespace,
        ServiceAccount:       pod.Spec.ServiceAccountName,
    }

    // Call policy engine
    policyEngineEndpoint := os.Getenv("POLICY_ENGINE_ENDPOINT")
    if policyEngineEndpoint == "" {
        policyEngineEndpoint = "http://policy-engine:8080/validate"
    }

    policyEngine := NewPolicyEngine(policyEngineEndpoint)
    validationResp, err := policyEngine.Validate(validationReq)
    if err != nil {
        logger.Errorf("Policy engine validation failed: %v", err)
        admissionResponse.Allowed = false
        admissionResponse.Result = &metav1.Status{
            Message: fmt.Sprintf("Policy engine validation failed: %v", err),
        }
    } else {
        admissionResponse.Allowed = validationResp.Allowed
        if !validationResp.Allowed {
            admissionResponse.Result = &metav1.Status{
                Message: validationResp.Message,
            }
        }
        if len(validationResp.Warnings) > 0 {
            admissionResponse.Warnings = validationResp.Warnings
        }
    }

    sendResponse(w, admissionReview, admissionResponse)
}

