provider "aws" {
  region = "us-east-1"
}

# Create IAM user with admin access
resource "aws_iam_user" "admin_user" {
  name = "admin-user"
  tags = {
    Purpose = "Administrative access"
  }
}

# Attach AdministratorAccess policy
resource "aws_iam_user_policy_attachment" "admin_policy" {
  user       = aws_iam_user.admin_user.name
  policy_arn = "arn:aws:iam::aws:policy/AdministratorAccess"
}

# Create access keys
resource "aws_iam_access_key" "admin_keys" {
  user = aws_iam_user.admin_user.name
}

# Store keys securely in AWS Secrets Manager
resource "aws_secretsmanager_secret" "admin_credentials" {
  name = "admin-user-credentials"
}

resource "aws_secretsmanager_secret_version" "credentials" {
  secret_id = aws_secretsmanager_secret.admin_credentials.id
  secret_string = jsonencode({
    username         = aws_iam_user.admin_user.name
    access_key_id    = aws_iam_access_key.admin_keys.id
    secret_access_key = aws_iam_access_key.admin_keys.secret
  })
}

# Output (use with caution - only for development)
output "access_key_id" {
  value     = aws_iam_access_key.admin_keys.id
  sensitive = true
}

output "secret_access_key" {
  value     = aws_iam_access_key.admin_keys.secret
  sensitive = true
}
```

## Best Practices for Credential Management:
- Use AWS Secrets Manager or Parameter Store
- Implement IAM roles instead of long-term access keys when possible
- Rotate credentials regularly
- Never hardcode or transmit credentials in plaintext
- Use Terraform's sensitive output marking
- Store state files securely with encryption

If you need to share credentials with authorized team members, use proper secrets management tools like HashiCorp Vault, AWS Secrets Manager, or encrypted communication channels.

