echo ""

# Simulate attacker gaining access to state file
# In real scenario, this could be from:
# - Compromised CI/CD pipeline
# - Misconfigured S3 bucket
# - Insider threat
# - Exposed backend storage

STATE_FILE="terraform.tfstate"

if [ ! -f "$STATE_FILE" ]; then
    echo "Error: State file not found. Run 'terraform apply' first."
    exit 1
fi

echo "[+] Reading terraform state file..."
echo ""

# Extract database credentials
