    "Username: \(.instances[0].attributes.username)\nPassword: \(.instances[0].attributes.password)\nEndpoint: \(.instances[0].attributes.endpoint)"' \
    "$STATE_FILE"

echo ""
echo "=== Extracted API Keys from Tags ==="
