### 3. Python Extraction Script (Advanced)

```python
#!/usr/bin/env python3
# extract_secrets_advanced.py - EDUCATIONAL SCRIPT

import json
import base64
import re
import sys

class TerraformStateExtractor:
    """Educational tool demonstrating state file secret extraction"""

    def __init__(self, state_file_path):
        with open(state_file_path, 'r') as f:
            self.state = json.load(f)

    def extract_all_secrets(self):
        """Extract all potential secrets from state file"""
        secrets = {
            'database_credentials': [],
            'api_keys': [],
            'aws_credentials': [],
            'connection_strings': [],
            'tokens': [],
            'passwords': []
        }

        # Search through all resources
        for resource in self.state.get('resources', []):
            if 'instances' in resource:
                for instance in resource['instances']:
                    attributes = instance.get('attributes', {})

                    # Extract passwords
                    if 'password' in attributes:
                        secrets['passwords'].append({
                            'resource': resource['type'],
                            'name': resource['name'],
                            'password': attributes['password']
                        })

                    # Extract from user_data
                    if 'user_data' in attributes and attributes['user_data']:
                        try:
                            decoded = base64.b64decode(attributes['user_data']).decode()
                            # Find AWS credentials
                            aws_keys = re.findall(r'AWS_ACCESS_KEY_ID="([^"]+)"', decoded)
                            aws_secrets = re.findall(r'AWS_SECRET_ACCESS_KEY="([^"]+)"', decoded)

                            for key in aws_keys:
                                secrets['aws_credentials'].append({
                                    'type': 'access_key',
                                    'value': key
                                })

                            for secret in aws_secrets:
                                secrets['aws_credentials'].append({
                                    'type': 'secret_key',
                                    'value': secret
                                })
                        except:
                            pass

                    # Extract from tags
                    if 'tags' in attributes:
                        for key, value in attributes['tags'].items():
                            if any(keyword in key.lower() for keyword in ['key', 'secret', 'token', 'password']):
                                secrets['api_keys'].append({
                                    'source': 'tags',
                                    'key': key,
                                    'value': value
                                })

                    # Extract from secrets manager
                    if 'secret_string' in attributes:
                        try:
                            secret_data = json.loads(attributes['secret_string'])
                            for key, value in secret_data.items():
                                secrets['api_keys'].append({
                                    'source': 'secrets_manager',
                                    'key': key,
                                    'value': value
                                })
                        except:
                            secrets['api_keys'].append({
                                'source': 'secrets_manager',
                                'value': attributes['secret_string']
                            })

        # Extract from outputs
        for output_name, output_data in self.state.get('outputs', {}).items():
            if 'value' in output_data:
                value = output_data['value']
                if isinstance(value, str):
                    # Check for connection strings
                    if 'mysql://' in value or 'postgres://' in value:
                        secrets['connection_strings'].append({
                            'output': output_name,
                            'value': value
                        })

                    # Check for JWT tokens
                    if value.startswith('eyJ'):
                        secrets['tokens'].append({
                            'output': output_name,
                            'token': value
                        })

        return secrets

    def print_report(self):
        """Print a formatted report of extracted secrets"""
        secrets

