      version = "~> 5.0"
    }
  }
  required_version = ">= 1.0"
}

provider "aws" {
  region = var.aws_region
}

# ============================================
# VULNERABILITY 1: Overly Permissive IAM Policies
# ============================================

# BAD PRACTICE: Wildcard permissions in IAM policy
resource "aws_iam_policy" "overly_permissive_policy" {
  name        = "overly-permissive-policy-${var.environment}"
  description = "DANGEROUS: Policy with excessive permissions"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        # VULNERABILITY: Allows all actions on all resources
        Effect   = "Allow"
        Action   = ["*"]  # Should be restricted to specific actions
        Resource = ["*"]  # Should be restricted to specific resources
      },
      {
        # VULNERABILITY: Administrative access without conditions
        Effect   = "Allow"
        Action   = [
          "iam:*",
          "ec2:*",
          "s3:*",
          "rds:*",
          "lambda:*"
        ]
        Resource = ["*"]
      }
    ]
  })
}

# BAD PRACTICE: IAM role with overly broad trust policy
resource "aws_iam_role" "vulnerable_role" {
  name = "vulnerable-role-${var.environment}"

  # VULNERABILITY: Trusts any AWS account
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "*"  # Should be restricted to specific accounts/roles
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Attach the overly permissive policy to the role
resource "aws_iam_role_policy_attachment" "vulnerable_attachment" {
  role       = aws_iam_role.vulnerable_role.name
  policy_arn = aws_iam_policy.overly_permissive_policy.arn
}

# BAD PRACTICE: IAM user with hardcoded credentials
resource "aws_iam_user" "vulnerable_user" {
  name = "vulnerable-user-${var.environment}"
  # VULNERABILITY: No MFA enforcement, no password policy
}

# VULNERABILITY: Access key with no rotation policy
resource "aws_iam_access_key" "vulnerable_key" {
  user = aws_iam_user.vulnerable_user.name
  # VULNERABILITY: No expiration or rotation mechanism
}

# BAD PRACTICE: Inline policy with excessive permissions
resource "aws_iam_user_policy" "vulnerable_inline_policy" {
  name = "vulnerable-inline-policy"
