I'll create a comprehensive Terraform configuration for cross-account disaster recovery of S3 buckets and RDS snapshots. This solution includes both the source account setup and the DR account configuration.

## Directory Structure

```
disaster-recovery/
├── source-account/
│   ├── main.tf
│   ├── variables.tf
│   ├── outputs.tf
│   └── iam.tf
├── dr-account/
│   ├── main.tf
│   ├── variables.tf
│   ├── outputs.tf
│   └── iam.tf
└── modules/
    ├── s3-replication/
    │   ├── main.tf
    │   ├── variables.tf
    │   └── outputs.tf
    └── rds-replication/
        ├── main.tf
        ├── variables.tf
        └── outputs.tf
```

## Source Account Configuration

### source-account/variables.tf
```hcl
variable "aws_region" {
  description = "AWS region for source account"
  type        = string
  default     = "us-east-1"
}

variable "dr_account_id" {
  description = "AWS account ID for disaster recovery"
  type        = string
}

variable "source_account_id" {
  description = "Source AWS account ID"
  type        = string
}

variable "environment" {
  description = "Environment name"
  type        = string
  default     = "production"
}

variable "s3_buckets_to_replicate" {
  description = "List of S3 buckets to replicate to DR account"
  type = list(object({
    name                = string
    versioning_enabled  = optional(bool, true)
    replication_rules   = optional(list(object({
      id                = string
      prefix            = optional(string, "")
      delete_marker_replication = optional(bool, true)
    })))
  }))
  default = []
}

variable "rds_instances_to_backup" {
  description = "List of RDS instances to create cross-account snapshots"
  type = list(object({
    identifier         = string
    snapshot_schedule  = optional(string, "rate(24 hours)")
    retention_days     = optional(number, 30)
  }))
  default = []
}

variable "tags" {
  description = "Common tags for all resources"
  type        = map(string)
  default = {
    Environment = "production"
    ManagedBy   = "terraform"
    Purpose     = "disaster-recovery"
  }
}
```

### source-account/iam.tf
```hcl
# IAM Role for S3 Replication
resource "aws_iam_role" "s3_replication_role" {
  name = "s3-cross-account-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_policy" "s3_replication_policy" {
  name = "s3-cross-account-replication-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = [for bucket in var.s3_buckets_to_replicate : "arn:aws:s3:::${bucket.name}"]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Resource = [for bucket in var.s3_buckets_to_replicate : "arn:aws:s3:::${bucket.name}/*"]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Resource = [for bucket in var.s3_buckets_to_replicate : "arn:aws:s3:::${bucket.name}-dr/*"]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "s3_replication_attachment" {
  role       = aws_iam_role.s3_replication_role.name
  policy_arn = aws_iam_policy.s3_replication_policy.arn
}

# IAM Role for RDS Snapshot Sharing
resource "aws_iam_role" "rds_snapshot_share_role" {
  name = "rds-cross-account-snapshot-share-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "events.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_policy" "rds_snapshot_share_policy" {
  name = "rds-cross-account-snapshot-share-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "rds:CreateDBSnapshot",
          "rds:DescribeDBSnapshots",
          "rds:ModifyDBSnapshotAttribute",
          "rds:CopyDBSnapshot"
        ]
        Resource = [for instance in var.rds_instances_to_backup : "arn:aws:rds:${var.aws_region}:${var.source_account_id}:snapshot:dr-*"]
      },
      {
        Effect = "Allow"
        Action = [
          "rds:DescribeDBInstances"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "rds_snapshot_share_attachment" {
  role       = aws_iam_role.rds_snapshot_share_role.name
  policy_arn = aws_iam_policy.rds_snapshot_share_policy.arn
}

# Lambda execution role for RDS snapshot automation
resource "aws_iam_role" "rds_snapshot_lambda_role" {
  name = "rds-snapshot-lambda-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_policy" "rds_snapshot_lambda_policy" {
  name = "rds-snapshot-lambda-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "rds:CreateDBSnapshot",
          "rds:DescribeDBSnapshots",
          "rds:ModifyDBSnapshotAttribute",
          "rds:DeleteDBSnapshot",
          "rds:DescribeDBInstances"
