}

resource "aws_iam_role_policy_attachment" "rds_snapshot_lambda_attachment" {
  role       = aws_iam_role.rds_snapshot_lambda_role.name
  policy_arn = aws_iam_policy.rds_snapshot_lambda_policy.arn
}
```

### source-account/main.tf
```hcl
terraform {
