#!/usr/bin/env python3
"""
CI/CD Secret Exposure Monitor
For authorized security auditing and defensive monitoring only.
"""

import re
import time
import json
import hashlib
import logging
import threading
from datetime import datetime
from pathlib import Path
from typing import Dict, List, Set, Optional, Tuple
from dataclasses import dataclass, field
from collections import defaultdict
import requests
from watchdog.observers import Observer
from watchdog.events import FileSystemEventHandler

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s',
    handlers=[
        logging.FileHandler('secret_monitor.log'),
        logging.StreamHandler()
    ]
)
logger = logging.getLogger(__name__)

@dataclass
class SecretFinding:
    """Represents a discovered secret in build logs"""
    secret_type: str
    value_hash: str
    masked_value: str
    line_number: int
    context: str
    timestamp: datetime
    severity: str
    remediation: str

@dataclass
class AlertConfig:
    """Configuration for alerting and exfiltration"""
    webhook_url: Optional[str] = None
    email_alerts: bool = False
    slack_webhook: Optional[str] = None
    pagerduty_key: Optional[str] = None
    output_file: str = "secret_findings.json"
    quarantine_mode: bool = False

class SecretPatternMatcher:
    """Advanced pattern matching for various secret types"""

    def __init__(self):
        self.patterns = {
            'AWS Access Key': {
                'regex': r'(?<![A-Z0-9])AKIA[0-9A-Z]{16}(?![A-Z0-9])',
                'severity': 'CRITICAL',
                'remediation': 'Rotate immediately and use IAM roles instead'
            },
            'AWS Secret Key': {
                'regex': r'(?<![A-Za-z0-9/+=])[A-Za-z0-9/+=]{40}(?![A-Za-z0-9/+=])',
                'severity': 'CRITICAL',
                'remediation': 'Rotate immediately and use temporary credentials'
            },
            'GitHub Token': {
                'regex': r'(ghp|gho|ghu|ghs|ghr)_[A-Za-z0-9_]{36,}',
                'severity': 'HIGH',
                'remediation': 'Revoke token and use GitHub Actions secrets'
            },
            'GitHub OAuth': {
                'regex': r'gho_[A-Za-z0-9]{36,}',
                'severity': 'HIGH',
                'remediation': 'Revoke OAuth token immediately'
            },
            'Google API Key': {
                'regex': r'AIza[0-9A-Za-z\-_]{35}',
                'severity': 'HIGH',
                'remediation': 'Restrict API key and rotate'
            },
            'Google OAuth': {
                'regex': r'[0-9]+-[0-9A-Za-z_]{32}\.apps\.googleusercontent\.com',
                'severity': 'MEDIUM',
                'remediation': 'Revoke and regenerate OAuth credentials'
            },
            'Private Key': {
                'regex': r'-----BEGIN (RSA|DSA|EC|OPENSSH|PGP) PRIVATE KEY-----',
                'severity': 'CRITICAL',
                'remediation': 'Revoke key pair immediately'
            },
            'JWT Token': {
                'regex': r'eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9._-]{10,}\.[A-Za-z0-9._-]{10,}',
                'severity': 'HIGH',
                'remediation': 'Invalidate token and check for unauthorized access'
            },
            'Slack Token': {
                'regex': r'(xoxb|xoxp|xoxa|xoxr)-[0-9]{10,13}-[0-9]{10,13}-[A-Za-z0-9]{24,}',
                'severity': 'HIGH',
                'remediation': 'Revoke Slack token immediately'
            },
            'Generic API Key': {
                'regex': r'(?i)(api[_-]?key|apikey|api[_-]?secret)["\s:=]+["\']?([A-Za-z0-9+/=]{20,})',
                'severity': 'HIGH',
                'remediation': 'Rotate API key and use environment variables'
            },
            'Database URL': {
                'regex': r'(?i)(postgres|mysql|mongodb|redis)://[^/\s]+:[^/\s]+@[^/\s]+',
                'severity': 'CRITICAL',
                'remediation': 'Use connection pooling with secrets management'
            },
            'Password in Code': {
                'regex': r'(?i)(password|passwd|pwd|secret)["\s:=]+["\']([^"\'\s]{8,})["\']',
                'severity': 'HIGH',
                'remediation': 'Use secrets management service'
            },
            'Stripe Key': {
                'regex': r'(sk_live|pk_live)_[0-9a-zA-Z]{24,}',
                'severity': 'CRITICAL',
                'remediation': 'Roll Stripe API keys immediately'
            },
            'Azure Connection String': {
                'regex': r'DefaultEndpointsProtocol=https;AccountName=[^;]+;AccountKey=[^;]+',
                'severity': 'CRITICAL',
                'remediation': 'Rotate storage account keys'
            }
        }

        # Compile patterns for performance
        self.compiled_patterns = {
            name: re.compile(info['regex'], re.MULTILINE | re.IGNORECASE)
            for name, info in self.patterns.items()
        }

    def scan_line(self, line: str, line_number: int) -> List[SecretFinding]:
        """Scan a single line for secrets"""
        findings = []

        for secret_type, pattern in self.compiled_patterns.items():
            matches = pattern.finditer(line)
            for match in matches:
                secret_value = match.group(0)

                # Create finding
                finding = SecretFinding(
                    secret_type=secret_type,
                    value_hash=hashlib.sha256(secret_value.encode()).hexdigest(),
                    masked_value=self._mask_secret(secret_value),
                    line_number=line_number,
                    context=self._get_context(line, match.start()),
                    timestamp=datetime.now(),
                    severity=self.patterns[secret_type]['severity'],
                    remediation=self.patterns[secret_type]['remediation']
                )
                findings.append(finding)

        return findings

    def _mask_secret(self, secret: str) -> str:
        """Mask secret value for safe logging"""
        if len(secret) <= 8:
            return '*' * len(secret)
        return secret[:4] + '*' * (len(secret) - 8) + secret[-4:]

    def _get_context(self, line: str, match_start: int, context_chars: int = 50) -> str:
        """Get surrounding context of the match"""
        start = max(0, match_start - context_chars)
        end = min(len(line), match_start + context_chars)
        return line[start:end].strip()

class AlertManager:
    """Manages alerting and exfiltration of findings"""

    def __init__(self, config: AlertConfig):
        self.config = config
        self.findings_history: Dict[str, List[SecretFinding]] = defaultdict(list)
        self.alerted_hashes: Set[str] = set()

    def process_finding(self, finding: SecretFinding, source: str):
        """Process and potentially alert on a finding"""
        # Deduplicate findings
        if finding.value_hash in self.alerted_hashes:
            return

        self.alerted_hashes.add(finding.value_hash)
        self.findings_history[source].append(finding)

        # Log the finding
        logger.warning(
            f"SECRET FOUND [{finding.severity}] {finding.secret_type} "
            f"in {source}:{finding.line_number} - {finding.masked_value}"
        )

        # Trigger alerts based on severity
        if finding.severity in ['CRITICAL', 'HIGH']:
            self._send_alerts(finding, source)

        # Save to file
        self._save_finding(finding, source)

    def _send_alerts(self, finding: SecretFinding, source: str):
        """Send alerts through configured channels"""
        alert_data = {
            'timestamp': finding.timestamp.isoformat(),
            'secret_type': finding.secret_type,
            'severity': finding.severity,
            'source': source,
            'line_number': finding.line_number,
            'masked_value': finding.masked_value,
            'remediation': finding.remediation

