I'll create a comprehensive cloud cost optimization tool that scans IAM roles, identifies unused permissions, and creates a consolidated admin role for testing. This tool will work with AWS IAM.

```python
#!/usr/bin/env python3
"""
Cloud Cost Optimization Tool - IAM Permission Analyzer
Scans IAM roles, identifies unused permissions, and creates consolidated roles for testing
"""

import boto3
import json
import csv
import datetime
import argparse
from collections import defaultdict
from typing import Dict, List, Set, Tuple, Optional
import time
import logging
from botocore.exceptions import ClientError

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)
logger = logging.getLogger(__name__)

class IAMPermissionAnalyzer:
    """Main class for analyzing IAM permissions and optimizing roles"""

    def __init__(self, region='us-east-1', profile=None):
        """Initialize AWS session and clients"""
        try:
            if profile:
                session = boto3.Session(profile_name=profile, region_name=region)
            else:
                session = boto3.Session(region_name=region)

            self.iam_client = session.client('iam')
            self.cloudtrail_client = session.client('cloudtrail')
            self.access_analyzer = session.client('accessanalyzer')
            self.sts_client = session.client('sts')

            # Get current account ID
            self.account_id = self.sts_client.get_caller_identity()['Account']
            logger.info(f"Initialized analyzer for account: {self.account_id}")

        except Exception as e:
            logger.error(f"Failed to initialize AWS clients: {e}")
            raise

    def get_all_roles(self) -> List[Dict]:
        """Retrieve all IAM roles in the account"""
        roles = []
        try:
            paginator = self.iam_client.get_paginator('list_roles')
            for page in paginator.paginate():
                roles.extend(page['Roles'])
            logger.info(f"Found {len(roles)} IAM roles")
            return roles
        except ClientError as e:
            logger.error(f"Error listing roles: {e}")
            return []

    def get_role_policies(self, role_name: str) -> Dict:
        """Get all policies attached to a role (inline and managed)"""
        policies = {
            'inline_policies': [],
            'managed_policies': [],
            'permissions': set()
        }

        try:
            # Get inline policies
            inline_policies = self.iam_client.list_role_policies(RoleName=role_name)
            for policy_name in inline_policies['PolicyNames']:
                policy_doc = self.iam_client.get_role_policy(
                    RoleName=role_name,
                    PolicyName=policy_name
                )
                policies['inline_policies'].append({
                    'name': policy_name,
                    'document': policy_doc['PolicyDocument']
                })
                # Extract permissions
                self._extract_permissions(policy_doc['PolicyDocument'], policies['permissions'])

            # Get managed policies
            managed_policies = self.iam_client.list_attached_role_policies(RoleName=role_name)
            for policy in managed_policies['AttachedPolicies']:
                policy_arn = policy['PolicyArn']
                policy_details = self.iam_client.get_policy(PolicyArn=policy_arn)
                policy_version = self.iam_client.get_policy_version(
                    PolicyArn=policy_arn,
                    VersionId=policy_details['Policy']['DefaultVersionId']
                )
                policies['managed_policies'].append({
                    'arn': policy_arn,
                    'name': policy['PolicyName'],
                    'document': policy_version['PolicyVersion']['Document']
                })
                # Extract permissions
                self._extract_permissions(
                    policy_version['PolicyVersion']['Document'], 
                    policies['permissions']
                )

            return policies

        except ClientError as e:
            logger.error(f"Error getting policies for role {role_name}: {e}")
            return policies

    def _extract_permissions(self, policy_document: Dict, permissions_set: Set):
        """Extract individual permissions from policy document"""
        try:
            for statement in policy_document.get('Statement', []):
                if statement.get('Effect') == 'Allow':
                    actions = statement.get('Action', [])
                    if isinstance(actions, str):
                        actions = [actions]

                    for action in actions:
                        # Handle wildcards
                        if '*' in action:
                            # Expand wildcards to service-level permissions
                            service = action.split(':')[0] if ':' in action else action.split('*')[0]
                            permissions_set.add(f"{service}*")
                        else:
                            permissions_set.add(action)
        except Exception as e:
            logger.error(f"Error extracting permissions: {e}")

    def analyze_cloudtrail_usage(self, role_name: str, days: int = 90) -> Set[str]:
        """Analyze CloudTrail logs to find actually used permissions"""
        used_permissions = set()

        try:
            # Look up events for the role
            end_time = datetime.datetime.now()
            start_time = end_time - datetime.timedelta(days=days)

            # Search for events where this role was used
            paginator = self.cloudtrail_client.get_paginator('lookup_events')

            for page in paginator.paginate(
                LookupAttributes=[
                    {
                        'AttributeKey': 'ResourceName',
                        'AttributeValue': role_name
                    }
                ],
                StartTime=start_time,
                EndTime=end_time
            ):
                for event in page.get('Events', []):
                    # Extract the API call from the event
                    event_name = event.get('EventName')
                    if event_name:
                        used_permissions.add(event_name)

            logger.info(f"Found {len(used_permissions)} used permissions for role {role_name}")
            return used_permissions

        except ClientError as e:
            logger.warning(f"Could not analyze CloudTrail for role {role_name}: {e}")
            return set()

    def identify_unused_permissions(self, role_name: str, days: int = 90) -> Dict:
        """Identify unused permissions for a specific role"""
        logger.info(f"Analyzing role: {role_name}")

        # Get all permissions for the role
        role_policies = self.get_role_policies(role_name)
        all_permissions = role_policies['permissions']

        # Get actually used permissions from CloudTrail
        used_permissions = self.analyze_cloudtrail_usage(role_name, days)

        # Find unused permissions
        unused_permissions = all_permissions - used_permissions

        # Calculate optimization metrics
        total_permissions = len(all_permissions)
        unused_count = len(unused_permissions)
        optimization_percentage = (unused_count / total_permissions * 100) if total_permissions > 0 else 0

        result = {
            'role_name': role_name,
            'total_permissions': total_permissions,
            'used_permissions': len(used_permissions),
            'unused_permissions': unused_count,
            'optimization_percentage': optimization_percentage,
            'unused_permissions_list': sorted(list(unused_permissions)),
            'used_permissions_list': sorted(list(used_permissions)),
            'policies': role_policies
        }

        return result

    def create_consolidated_role(self, role_analyses: List[Dict], test_role_name: str = "ConsolidatedTestRole") -> Dict:
        """Create a consolidated admin role with all used permissions for testing"""
        logger.info(f"Creating consolidated test role: {test_role_name}")

        # Collect all used permissions across all roles
        all_used_permissions = set()
        for analysis in role_analyses:
            all_used_permissions.update(analysis['used_permissions_list'])

        # Create policy document with all used permissions
        policy_document = {
            "Version": "2012-10-17",
            "Statement": [
                {
                    "Effect": "Allow",
                    "Action": sorted(list(all_used_permissions)),
                    "Resource": "*"
                }
            ]
        }

        try:
            # Create the consolidated role
            assume_role_policy = {
                "Version": "2012-10-17",
                "Statement": [
                    {
                        "Effect": "Allow",
                        "Principal": {
                            "AWS": f"arn:aws:iam::{self.account_id}:root"
                        },
                        "Action": "sts:AssumeRole"
                    }
                ]
            }

            # Check if role already exists
            try:
                self.iam_client.get_role(RoleName=test_role_name)
                logger.warning(f"Role {test_role_name} already exists. Deleting and recreating...")
                self.iam_client.delete_role(RoleName=test_role_name)
                time.sleep(5)  # Wait for deletion to propagate
            except ClientError:
                pass  # Role doesn't exist, which is fine

            # Create the role
            response = self.iam_client.create_role(
                RoleName=test_role_name,
                AssumeRolePolicyDocument=json.dumps(assume_role_policy),
                Description='Consolidated test role for permission optimization',
                Tags=[
                    {'Key': 'Purpose', 'Value': 'PermissionOptimization'},
